async fn arbitrage_api(
    State(state): State<WebState>,
    headers: HeaderMap,
    Query(query): Query<ArbitragePageQuery>,
) -> Result<Response, WebError> {
    if !has_arbitrage_api_access(&state, &headers).await? {
        return Ok((
            StatusCode::UNAUTHORIZED,
            Json(json!({"error": "auth required"})),
        )
            .into_response());
    };
    let minutes = query.minutes.unwrap_or(60).clamp(1, 24 * 60);
    let limit = query.limit.unwrap_or(50).clamp(10, 200);
    let (recent, hot_pools, hot_routes) = tokio::try_join!(
        load_arbitrage_recent(&state, minutes, limit),
        load_arbitrage_hot_pools(&state, minutes, 25),
        load_arbitrage_hot_routes(&state, minutes, 25),
    )?;
    Ok(Json(json!({
        "chain_id": state.default_chain_id,
        "window_minutes": minutes,
        "recent_limit": limit,
        "recent_candidates": recent.iter().map(|item| json!({
            "tx_hash": item.tx_hash,
            "block_number": item.block_number,
            "block_timestamp": item.block_timestamp,
            "sender_address": item.sender_address,
            "entry_contract": item.entry_contract,
            "swap_log_count": item.swap_log_count,
            "distinct_pool_count": item.distinct_pool_count,
            "route": item.route,
            "confirmation_status": item.confirmation_status,
            "profit_token_address": item.profit_token_address,
            "profit_amount_raw": item.profit_amount_raw,
        })).collect::<Vec<_>>(),
        "hot_pools": hot_pools.iter().map(|item| json!({
            "pool_address": item.pool_address,
            "tx_count": item.tx_count,
            "swap_log_count": item.swap_log_count,
            "unique_senders": item.unique_senders,
            "unique_routes": item.unique_routes,
            "last_seen": item.last_seen,
            "sample_tx_hashes": item.sample_tx_hashes,
        })).collect::<Vec<_>>(),
        "hot_routes": hot_routes.iter().map(|item| json!({
            "route_fingerprint": item.route_fingerprint,
            "route": item.route,
            "tx_count": item.tx_count,
            "swap_log_count": item.swap_log_count,
            "unique_senders": item.unique_senders,
            "last_seen": item.last_seen,
            "sample_tx_hashes": item.sample_tx_hashes,
        })).collect::<Vec<_>>(),
    }))
    .into_response())
}

async fn has_arbitrage_api_access(state: &WebState, headers: &HeaderMap) -> Result<bool, WebError> {
    if current_user(state, headers).await?.is_some() {
        return Ok(true);
    }
    let route = chain_route(state, state.default_chain_id)?;
    let Some(indexer_api_base_url) = route.indexer_api_base_url.as_deref() else {
        return Ok(false);
    };
    let Some(api_key) = headers
        .get(header::AUTHORIZATION)
        .or_else(|| headers.get("x-api-key"))
        .cloned()
    else {
        return Ok(false);
    };
    let request = if headers.contains_key(header::AUTHORIZATION) {
        state
            .client
            .get(format!(
                "{}/progress",
                indexer_api_base_url.trim_end_matches('/')
            ))
            .header(header::AUTHORIZATION, api_key)
    } else {
        state
            .client
            .get(format!(
                "{}/progress",
                indexer_api_base_url.trim_end_matches('/')
            ))
            .header("x-api-key", api_key)
    };
    Ok(request
        .send()
        .await
        .map(|response| response.status().is_success())
        .unwrap_or(false))
}

async fn swaps_block_range_api(
    State(state): State<WebState>,
    headers: HeaderMap,
    Query(query): Query<SwapBlockRangeQuery>,
) -> Result<Response, WebError> {
    let Some(_user) = current_user(&state, &headers).await? else {
        return Ok((
            StatusCode::UNAUTHORIZED,
            Json(json!({"error": "auth required"})),
        )
            .into_response());
    };
    if query.from_block > query.to_block {
        return Ok((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "from_block must be <= to_block"})),
        )
            .into_response());
    }
    let block_count = query
        .to_block
        .saturating_sub(query.from_block)
        .saturating_add(1);
    if block_count > SWAP_BLOCK_RANGE_MAX_BLOCKS {
        return Ok((
            StatusCode::BAD_REQUEST,
            Json(json!({
                "error": format!("block range too large; max {SWAP_BLOCK_RANGE_MAX_BLOCKS} blocks")
            })),
        )
            .into_response());
    }
    let min_swaps = query.min_swaps.unwrap_or(1).clamp(1, 100);
    let tx_limit = query.tx_limit.unwrap_or(100).clamp(1, 500);
    let pool_limit = query.pool_limit.unwrap_or(50).clamp(1, 200);
    let summary_query = cryptohouse_swaps_summary_query(query.from_block, query.to_block);
    let txs_query =
        cryptohouse_swap_txs_query(query.from_block, query.to_block, min_swaps, tx_limit);
    let pools_query =
        cryptohouse_hot_swap_pools_query(query.from_block, query.to_block, pool_limit);
    let (summary, swap_txs, hot_pools) = tokio::try_join!(
        cryptohouse_json_each_row(&state, &summary_query),
        cryptohouse_json_each_row(&state, &txs_query),
        cryptohouse_json_each_row(&state, &pools_query),
    )?;
    Ok(Json(json!({
        "from_block": query.from_block,
        "to_block": query.to_block,
        "block_count": block_count,
        "min_swaps": min_swaps,
        "tx_limit": tx_limit,
        "pool_limit": pool_limit,
        "summary": summary.first().cloned().unwrap_or_else(|| json!({})),
        "swap_txs": swap_txs,
        "hot_pools": hot_pools,
    }))
    .into_response())
}

async fn cryptohouse_json_each_row(
    state: &WebState,
    sql: &str,
) -> Result<Vec<serde_json::Value>, WebError> {
    let response = state
        .client
        .post(&state.cryptohouse_url)
        .body(sql.to_owned())
        .send()
        .await
        .map_err(WebError::upstream)?;
    let status = response.status();
    let body = response.text().await.map_err(WebError::upstream)?;
    if !status.is_success() {
        return Err(WebError::bad_gateway(format!(
            "cryptohouse query failed: {status} {}",
            truncate_for_display(&body, 300)
        )));
    }
    body.lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(|line| serde_json::from_str(line).map_err(|err| WebError::internal(err.to_string())))
        .collect()
}

fn cryptohouse_swaps_summary_query(from_block: u64, to_block: u64) -> String {
    format!(
        r#"
SELECT
  count() AS swap_log_count,
  uniqExact(transaction_hash) AS swap_tx_count,
  uniqExact(address) AS pool_count,
  min(block_timestamp) AS first_seen,
  max(block_timestamp) AS last_seen
FROM base.logs
WHERE block_number BETWEEN {from_block} AND {to_block}
  AND (
    position(topics, '{UNISWAP_V2_SWAP_TOPIC_HEX}') > 0
    OR position(topics, '{UNISWAP_V3_SWAP_TOPIC_HEX}') > 0
  )
FORMAT JSONEachRow
"#
    )
}

fn cryptohouse_swap_txs_query(
    from_block: u64,
    to_block: u64,
    min_swaps: u32,
    limit: u32,
) -> String {
    format!(
        r#"
SELECT
  l.block_number,
  l.transaction_hash,
  count() AS swap_log_count,
  countIf(position(l.topics, '{UNISWAP_V2_SWAP_TOPIC_HEX}') > 0) AS v2_swap_count,
  countIf(position(l.topics, '{UNISWAP_V3_SWAP_TOPIC_HEX}') > 0) AS v3_swap_count,
  uniqExact(l.address) AS distinct_pool_count,
  groupUniqArray(64)(l.address) AS pool_addresses,
  groupArray(128)(l.log_index) AS log_indexes,
  any(t.from_address) AS sender_address,
  any(t.to_address) AS entry_contract,
  toString(max(l.block_timestamp)) AS block_timestamp
FROM base.logs AS l
LEFT JOIN base.transactions AS t
  ON t.block_number = l.block_number
 AND t.hash = l.transaction_hash
WHERE l.block_number BETWEEN {from_block} AND {to_block}
  AND (
    position(l.topics, '{UNISWAP_V2_SWAP_TOPIC_HEX}') > 0
    OR position(l.topics, '{UNISWAP_V3_SWAP_TOPIC_HEX}') > 0
  )
GROUP BY l.block_number, l.transaction_hash
HAVING swap_log_count >= {min_swaps}
ORDER BY swap_log_count DESC, l.block_number DESC
LIMIT {limit}
FORMAT JSONEachRow
"#
    )
}

fn cryptohouse_hot_swap_pools_query(from_block: u64, to_block: u64, limit: u32) -> String {
    format!(
        r#"
SELECT
  address AS pool_address,
  count() AS swap_log_count,
  uniqExact(transaction_hash) AS tx_count,
  uniqExact(block_number) AS block_count,
  min(block_number) AS first_block,
  max(block_number) AS last_block,
  min(block_timestamp) AS first_seen,
  max(block_timestamp) AS last_seen,
  groupUniqArray(8)(transaction_hash) AS sample_tx_hashes
FROM base.logs
WHERE block_number BETWEEN {from_block} AND {to_block}
  AND (
    position(topics, '{UNISWAP_V2_SWAP_TOPIC_HEX}') > 0
    OR position(topics, '{UNISWAP_V3_SWAP_TOPIC_HEX}') > 0
  )
GROUP BY address
ORDER BY tx_count DESC, swap_log_count DESC, last_block DESC
LIMIT {limit}
FORMAT JSONEachRow
"#
    )
}

async fn load_arbitrage_recent(
    state: &WebState,
    minutes: i64,
    limit: i64,
) -> Result<Vec<ArbitrageRecentRow>, WebError> {
    let rows = sqlx::query(
        r#"
        select tx_hash, block_number, block_timestamp, sender_address, entry_contract,
               swap_log_count, distinct_pool_count, route,
               confirmation_status, profit_token_address, profit_amount_raw
        from arbitrage_candidates
        where chain_id = $1
          and block_timestamp >= now() - ($2::text || ' minutes')::interval
        order by block_timestamp desc nulls last, block_number desc, score desc
        limit $3
        "#,
    )
    .bind(state.default_chain_id as i64)
    .bind(minutes)
    .bind(limit)
    .fetch_all(&state.pool)
    .await
    .map_err(|err| WebError::internal(err.to_string()))?;
    Ok(rows
        .into_iter()
        .map(|row| ArbitrageRecentRow {
            tx_hash: row.get("tx_hash"),
            block_number: row.get("block_number"),
            block_timestamp: row.get("block_timestamp"),
            sender_address: row.get("sender_address"),
            entry_contract: row.get("entry_contract"),
            swap_log_count: row.get("swap_log_count"),
            distinct_pool_count: row.get("distinct_pool_count"),
            route: row.get("route"),
            confirmation_status: row.get("confirmation_status"),
            profit_token_address: row.get("profit_token_address"),
            profit_amount_raw: row.get("profit_amount_raw"),
        })
        .collect())
}

async fn load_tx_candidate_context(
    state: &WebState,
    chain_id: u64,
    tx_hash: &str,
) -> Result<Option<TxCandidateContext>, WebError> {
    let row = sqlx::query(
        r#"
        select c.chain_id, c.tx_hash, c.block_number, c.block_timestamp,
               c.detection_source, c.sender_address, c.entry_contract, c.score,
               c.swap_log_count, c.distinct_pool_count, c.route,
               c.route_fingerprint, c.confirmation_status,
               c.profit_token_address, c.profit_amount_raw,
               coalesce((
                 select array_agg(p.pool_address order by p.route_position nulls last, p.first_log_index, p.pool_address)
                 from arbitrage_candidate_pools p
                 where p.chain_id = c.chain_id and lower(p.tx_hash) = lower(c.tx_hash)
               ), array[]::text[]) as pool_addresses
        from arbitrage_candidates c
        where c.chain_id = $1 and lower(c.tx_hash) = lower($2)
        limit 1
        "#,
    )
    .bind(chain_id as i64)
    .bind(tx_hash.trim())
    .fetch_optional(&state.pool)
    .await
    .map_err(|err| WebError::internal(format!("load tx candidate context failed: {err}")))?;
    Ok(row.map(|row| TxCandidateContext {
        chain_id: row.get::<i64, _>("chain_id").max(0) as u64,
        tx_hash: row.get("tx_hash"),
        block_number: row.get("block_number"),
        block_timestamp: row.get("block_timestamp"),
        detection_source: row.get("detection_source"),
        sender_address: row.get("sender_address"),
        entry_contract: row.get("entry_contract"),
        score: row.get("score"),
        swap_log_count: row.get("swap_log_count"),
        distinct_pool_count: row.get("distinct_pool_count"),
        route: row.get("route"),
        route_fingerprint: row.get("route_fingerprint"),
        confirmation_status: row.get("confirmation_status"),
        profit_token_address: row.get("profit_token_address"),
        profit_amount_raw: row.get("profit_amount_raw"),
        pool_addresses: row.get("pool_addresses"),
    }))
}

async fn prepare_tx_analysis_payload(
    state: &WebState,
    envelope: AnalysisEnvelope,
) -> Result<serde_json::Value, WebError> {
    let analysis = &envelope.analysis;
    let recognizer_labels = analysis
        .recognizer_results
        .iter()
        .map(|item| item.label.clone())
        .collect::<Vec<_>>();
    let scenario_kind = analysis
        .scenario_outputs
        .pointer("/storyline/kind")
        .and_then(serde_json::Value::as_str);
    let arbitrage_recognized = recognizer_labels
        .iter()
        .any(|label| label == "arbitrage_like_activity")
        || scenario_kind == Some("arbitrage");
    let assessment_status = match analysis.status {
        crate::domain::enums::TransactionStatus::Failure => "analyzed_reverted",
        crate::domain::enums::TransactionStatus::Pending => "analyzed_pending",
        crate::domain::enums::TransactionStatus::Success if arbitrage_recognized => {
            "probable_arbitrage"
        }
        crate::domain::enums::TransactionStatus::Success => "analyzed_multi_pool_unconfirmed",
    };
    let assessment = json!({
        "method": "transaction_analysis_v1",
        "analysis_id": analysis.analysis_id,
        "input_digest": analysis.input_digest,
        "analysis_status": enum_label(&analysis.analysis_status),
        "transaction_status": enum_label(&analysis.status),
        "recognizer_labels": recognizer_labels,
        "scenario_kind": scenario_kind,
        "unresolved_count": analysis.unresolved_items.len(),
        "validation_count": analysis.validation_results.len(),
        "reason": match assessment_status {
            "analyzed_reverted" => "transaction did not execute successfully",
            "analyzed_pending" => "transaction execution status is still pending",
            "probable_arbitrage" => "transaction analysis produced an arbitrage-like signal; profit still requires complete priced net-flow and finality checks",
            _ => "multi-pool swap signal was analyzed but no arbitrage recognizer confirmed intent",
        }
    });
    sqlx::query(
        r#"
        update arbitrage_candidates
        set confirmation_status = case
              when confirmation_status like 'confirmed_%' then confirmation_status
              else $3
            end,
            confirmation_metadata = confirmation_metadata || $4,
            updated_at = now()
        where chain_id = $1 and lower(tx_hash) = lower($2)
        "#,
    )
    .bind(analysis.chain_id as i64)
    .bind(&analysis.tx_hash)
    .bind(assessment_status)
    .bind(SqlJson(assessment))
    .execute(&state.pool)
    .await
    .map_err(|err| WebError::internal(format!("update candidate assessment failed: {err}")))?;

    let candidate = load_tx_candidate_context(state, analysis.chain_id, &analysis.tx_hash).await?;
    let mut payload = serde_json::to_value(envelope)
        .map_err(|err| WebError::internal(format!("analysis payload encode failed: {err}")))?;
    if let (Some(candidate), Some(object)) = (candidate, payload.as_object_mut()) {
        object.insert(
            "candidate_context".to_owned(),
            serde_json::to_value(candidate).unwrap_or_default(),
        );
    }
    Ok(payload)
}

async fn load_arbitrage_hot_pools(
    state: &WebState,
    minutes: i64,
    limit: i64,
) -> Result<Vec<ArbitrageHotPoolRow>, WebError> {
    let rows = sqlx::query(
        r#"
        select
          p.pool_address,
          count(distinct p.tx_hash)::bigint as tx_count,
          coalesce(sum(p.swap_log_count), 0)::bigint as swap_log_count,
          count(distinct c.sender_address)::bigint as unique_senders,
          count(distinct c.route_fingerprint)::bigint as unique_routes,
          max(p.block_timestamp) as last_seen,
          coalesce(jsonb_agg(distinct p.tx_hash) filter (where p.tx_hash is not null), '[]'::jsonb) as sample_tx_hashes
        from arbitrage_candidate_pools p
        join arbitrage_candidates c on c.chain_id = p.chain_id and c.tx_hash = p.tx_hash
        where p.chain_id = $1
          and p.block_timestamp >= now() - ($2::text || ' minutes')::interval
        group by p.pool_address
        order by tx_count desc, swap_log_count desc, last_seen desc
        limit $3
        "#,
    )
    .bind(state.default_chain_id as i64)
    .bind(minutes)
    .bind(limit)
    .fetch_all(&state.pool)
    .await
    .map_err(|err| WebError::internal(err.to_string()))?;
    Ok(rows
        .into_iter()
        .map(|row| ArbitrageHotPoolRow {
            pool_address: row.get("pool_address"),
            tx_count: row.get("tx_count"),
            swap_log_count: row.get("swap_log_count"),
            unique_senders: row.get("unique_senders"),
            unique_routes: row.get("unique_routes"),
            last_seen: row.get("last_seen"),
            sample_tx_hashes: json_value_strings(
                row.get::<Option<serde_json::Value>, _>("sample_tx_hashes"),
            ),
        })
        .collect())
}

async fn load_arbitrage_hot_routes(
    state: &WebState,
    minutes: i64,
    limit: i64,
) -> Result<Vec<ArbitrageHotRouteRow>, WebError> {
    let rows = sqlx::query(
        r#"
        select route_fingerprint, route,
               count(*)::bigint as tx_count,
               coalesce(sum(swap_log_count), 0)::bigint as swap_log_count,
               count(distinct sender_address)::bigint as unique_senders,
               max(block_timestamp) as last_seen,
               coalesce(jsonb_agg(tx_hash order by block_timestamp desc) filter (where tx_hash is not null), '[]'::jsonb) as sample_tx_hashes
        from arbitrage_candidates
        where chain_id = $1
          and block_timestamp >= now() - ($2::text || ' minutes')::interval
          and route_fingerprint <> ''
        group by route_fingerprint, route
        order by tx_count desc, swap_log_count desc, last_seen desc
        limit $3
        "#,
    )
    .bind(state.default_chain_id as i64)
    .bind(minutes)
    .bind(limit)
    .fetch_all(&state.pool)
    .await
    .map_err(|err| WebError::internal(err.to_string()))?;
    Ok(rows
        .into_iter()
        .map(|row| ArbitrageHotRouteRow {
            route_fingerprint: row.get("route_fingerprint"),
            route: row.get("route"),
            tx_count: row.get("tx_count"),
            swap_log_count: row.get("swap_log_count"),
            unique_senders: row.get("unique_senders"),
            last_seen: row.get("last_seen"),
            sample_tx_hashes: json_value_strings(
                row.get::<Option<serde_json::Value>, _>("sample_tx_hashes"),
            ),
        })
        .collect())
}

