async fn cluster_status(
    State(state): State<WebState>,
    headers: HeaderMap,
    Query(query): Query<DashboardQuery>,
) -> Result<Response, WebError> {
    let Some(user) = current_user(&state, &headers).await? else {
        return Ok(Redirect::to("/auth?notice=auth-required").into_response());
    };
    let clusters = state
        .portal_service
        .list_clusters_for_user(user.user_id)
        .await?;
    let Some(cluster_id_raw) = query.cluster_id.as_deref() else {
        return Err(WebError::bad_request("cluster_id is required".to_owned()));
    };
    let cluster_id = Uuid::parse_str(cluster_id_raw)
        .map_err(|err| WebError::bad_request(format!("invalid cluster id: {err}")))?;
    let Some(cluster) = clusters
        .iter()
        .find(|cluster| cluster.cluster_id == cluster_id)
    else {
        return Err(WebError::bad_request(
            "cluster is not available for the current user".to_owned(),
        ));
    };
    let payload = load_cluster_live_response(
        &state,
        cluster.chain_id,
        cluster_id,
        query.start.as_deref(),
        query.end.as_deref(),
        &ClusterAnalysisTab::from_query(query.cluster_tab.as_deref()),
    )
    .await?;
    Ok(Json(payload).into_response())
}

async fn create_cluster(
    State(state): State<WebState>,
    headers: HeaderMap,
    Form(form): Form<CreateClusterForm>,
) -> Result<Response, WebError> {
    let Some(user) = current_user(&state, &headers).await? else {
        return Ok(Redirect::to("/auth?notice=auth-required").into_response());
    };
    let addresses = parse_cluster_addresses(&form.addresses)?;
    let chain_id = form.chain_id;
    let request = CreateClusterRequest {
        chain_id,
        owner_label: form.owner_label,
        name: form.name,
        description: form.description.filter(|value| !value.trim().is_empty()),
        addresses,
    };
    match api_post_json::<_, AddressCluster>(&state, chain_id, "/clusters", &request).await {
        Ok(cluster) => {
            state
                .portal_service
                .attach_cluster_to_user(user.user_id, cluster.cluster_id)
                .await?;
            Ok(redirect_response(&format!(
                "/app/clusters/{}?notice=cluster-created",
                cluster.cluster_id
            )))
        }
        Err(err) => {
            let query = DashboardQuery {
                tab: Some("clusters".to_owned()),
                cluster_id: None,
                start: None,
                end: None,
                cluster_tab: None,
                tx_page: None,
                tx_page_size: None,
                tx_behavior: None,
                tx_protocol: None,
                tx_sort_by: None,
                tx_sort_dir: None,
                notice: None,
                created_key: None,
            };
            render_dashboard_response(
                &state,
                user,
                query,
                None,
                None,
                Some(err.to_string()),
                None,
                None,
                None,
            )
            .await
        }
    }
}

async fn update_cluster(
    State(state): State<WebState>,
    headers: HeaderMap,
    Path(cluster_id): Path<String>,
    Form(form): Form<UpdateClusterForm>,
) -> Result<Response, WebError> {
    let Some(user) = current_user(&state, &headers).await? else {
        return Ok(Redirect::to("/auth?notice=auth-required").into_response());
    };
    let chain_id = ensure_user_owns_cluster(&state, user.user_id, &cluster_id).await?;
    if form.chain_id != chain_id {
        return Err(WebError::bad_request(
            "cluster chain cannot be changed from the web form".to_owned(),
        ));
    }
    let addresses = parse_cluster_addresses(&form.addresses)?;
    let request = CreateClusterRequest {
        chain_id,
        owner_label: form.owner_label,
        name: form.name,
        description: form.description.filter(|value| !value.trim().is_empty()),
        addresses,
    };
    match api_post_json::<_, AddressCluster>(
        &state,
        chain_id,
        &format!("/clusters/{cluster_id}/update"),
        &request,
    )
    .await
    {
        Ok(cluster) => Ok(redirect_response(&format!(
            "/app/clusters?cluster_id={}&notice=cluster-updated-needs-backfill",
            cluster.cluster_id
        ))),
        Err(err) => {
            let editable_cluster =
                load_editable_cluster_on_chain(&state, chain_id, Some(&cluster_id)).await?;
            render_dashboard_response(
                &state,
                user,
                DashboardQuery {
                    tab: Some("clusters".to_owned()),
                    cluster_id: Some(cluster_id),
                    start: None,
                    end: None,
                    cluster_tab: None,
                    tx_page: None,
                    tx_page_size: None,
                    tx_behavior: None,
                    tx_protocol: None,
                    tx_sort_by: None,
                    tx_sort_dir: None,
                    notice: None,
                    created_key: None,
                },
                editable_cluster.as_ref(),
                None,
                Some(err.to_string()),
                None,
                None,
                None,
            )
            .await
        }
    }
}

