fn render_address_analysis_link(chain_id: u64, address: &str, keep: usize) -> String {
    format!(
        r#"<a class="evidence-link" href="/app/address-analysis?chain_id={}&address={}" title="{}"><code>{}</code></a>"#,
        chain_id,
        urlencoding::encode(address),
        escape_html(address),
        escape_html(&truncate_middle(address, keep)),
    )
}

fn render_evidence_refs(refs: &[crate::domain::value_objects::EvidenceRef]) -> String {
    if refs.is_empty() {
        return "<div class=\"empty-state compact-empty\">No evidence references attached.</div>"
            .to_owned();
    }
    let rows = refs
        .iter()
        .take(20)
        .map(|item| {
            format!(
                r#"<tr><td><span class="badge">{}</span></td><td><code>{}</code></td><td>{}</td></tr>"#,
                escape_html(&enum_label(&item.kind)),
                escape_html(&item.reference),
                item.tx_hash
                    .as_deref()
                    .map(|hash| escape_html(&truncate_middle(hash, 8)))
                    .unwrap_or_else(|| "n/a".to_owned()),
            )
        })
        .collect::<Vec<_>>()
        .join("");
    let remainder = refs.len().saturating_sub(20);
    format!(
        r#"<details class="evidence-ref-details"><summary>Evidence references ({})</summary><div class="table-shell compact-table-shell"><table class="compact-table"><thead><tr><th>Kind</th><th>Reference</th><th>Tx</th></tr></thead><tbody>{}</tbody></table></div>{}</details>"#,
        refs.len(),
        rows,
        if remainder > 0 {
            format!(
                "<p class=\"panel-copy\">{} additional reference(s) omitted from this compact view.</p>",
                remainder
            )
        } else {
            String::new()
        }
    )
}

fn render_json_details(label: &str, value: &serde_json::Value, limit: usize) -> String {
    let raw = serde_json::to_string_pretty(value).unwrap_or_else(|_| "null".to_owned());
    let truncated = raw.chars().count() > limit;
    let preview = if truncated {
        format!(
            "{}\n… output truncated in this view",
            truncate_for_display(&raw, limit)
        )
    } else {
        raw
    };
    format!(
        r#"<details class="raw-json-shell"><summary>{}</summary><pre class="json-shell">{}</pre></details>"#,
        escape_html(label),
        escape_html(&preview),
    )
}

fn render_storyline_gap_explanation(scenario_outputs: &serde_json::Value) -> Option<String> {
    let storyline = scenario_outputs.get("storyline")?;
    let has_visible_lane = [
        "funding_sources",
        "repay_legs",
        "collateral_receipts",
        "disposition_legs",
        "cycle_legs",
        "exit_legs",
    ]
    .iter()
    .any(|key| {
        storyline
            .get(*key)
            .and_then(|value| value.as_array())
            .map(|items| !items.is_empty())
            .unwrap_or(false)
    });
    if has_visible_lane {
        return None;
    }
    Some(
        "LedgerFlow matched the protocol or method pattern, but the current flow reconstruction did not confidently attach concrete funding, repay, reward, or settlement legs yet. In practice this means the protocol match is ahead of the asset-leg attribution."
            .to_owned(),
    )
}

fn render_tx_report_meta_strip(
    analysis: &TransactionAnalysis,
    public_share: bool,
    share_action: &str,
    share_url: Option<&str>,
) -> String {
    let network = match analysis.chain_id {
        1 => "Ethereum",
        8453 => "Base",
        4663 => "Robinhood Chain",
        10 => "Optimism",
        42161 => "Arbitrum",
        _ => "EVM chain",
    };
    let block = analysis
        .block_number
        .map(|value| value.to_string())
        .unwrap_or_else(|| "n/a".to_owned());
    let timestamp = analysis
        .block_timestamp
        .map(|value| value.to_rfc3339().replace('T', " ").replace('Z', " UTC"))
        .unwrap_or_else(|| "n/a".to_owned());
    let facts = &analysis.normalized_execution_facts.derived_facts;
    let nonce = facts
        .get("nonce")
        .and_then(|value| value.as_u64())
        .map(|value| value.to_string());
    let tx_index = facts
        .get("tx_index")
        .and_then(|value| value.as_u64())
        .map(|value| value.to_string());
    let value_raw = facts
        .get("tx_value_raw")
        .and_then(|value| value.as_str())
        .unwrap_or(&analysis.value);
    let gas_used = facts
        .get("gas_used_raw")
        .and_then(|value| value.as_str())
        .filter(|value| !value.is_empty() && *value != "0");
    let gas_price = facts
        .get("effective_gas_price_raw")
        .and_then(|value| value.as_str())
        .filter(|value| !value.is_empty() && *value != "0")
        .map(format_gwei_from_wei);
    let tx_fee = facts
        .get("gas_cost_raw")
        .and_then(|value| value.as_str())
        .filter(|value| !value.is_empty() && *value != "0")
        .map(format_wei_eth_raw);
    let mut basic_fields = vec![
        render_basic_info_item(
            "Status",
            &format!(
                r#"<strong class="status-chip status-{}">{}</strong>"#,
                match analysis.status {
                    crate::domain::enums::TransactionStatus::Success => "success",
                    crate::domain::enums::TransactionStatus::Failure => "failure",
                    crate::domain::enums::TransactionStatus::Pending => "pending",
                },
                escape_html(&enum_label(&analysis.status))
            ),
        ),
        render_basic_info_item(
            "Network",
            &format!("<strong>{}</strong>", escape_html(network)),
        ),
        render_basic_info_item(
            "Block",
            &format!("<strong>{}</strong>", escape_html(&block)),
        ),
        render_basic_info_item(
            "Timestamp",
            &format!("<strong>{}</strong>", escape_html(&timestamp)),
        ),
        render_basic_info_item(
            "Value",
            &format!(
                "<strong>{}</strong>",
                escape_html(&format_wei_compact_decimal(value_raw))
            ),
        ),
        render_basic_info_item(
            "Sender",
            &format!(
                "<strong>{}</strong>",
                render_copyable_code(&analysis.from_address, 12)
            ),
        ),
        render_basic_info_item(
            "Receiver",
            &format!(
                "<strong>{}</strong>",
                analysis
                    .to_address
                    .as_deref()
                    .map(|value| render_copyable_code(value, 12))
                    .unwrap_or_else(|| "contract creation".to_owned())
            ),
        ),
    ];
    if let Some(nonce) = nonce {
        basic_fields.insert(
            4,
            render_basic_info_item(
                "Nonce",
                &format!("<strong>{}</strong>", escape_html(&nonce)),
            ),
        );
    }
    if let Some(tx_index) = tx_index {
        basic_fields.insert(
            4,
            render_basic_info_item(
                "Position in Block",
                &format!("<strong>{}</strong>", escape_html(&tx_index)),
            ),
        );
    }
    let mut other_fields = Vec::new();
    if let Some(gas_used) = gas_used {
        other_fields.push(render_basic_info_item(
            "Gas Used",
            &format!("<strong>{}</strong>", escape_html(gas_used)),
        ));
    }
    if let Some(gas_price) = gas_price.as_deref() {
        other_fields.push(render_basic_info_item(
            "Gas Price",
            &format!("<strong>{}</strong>", escape_html(gas_price)),
        ));
    }
    if let Some(tx_fee) = tx_fee.as_deref() {
        other_fields.push(render_basic_info_item(
            "Transaction Fee",
            &format!("<strong>{}</strong>", escape_html(tx_fee)),
        ));
    }
    other_fields.push(render_basic_info_item(
        "Event Count",
        &format!(
            "<strong>{}</strong>",
            analysis.normalized_execution_facts.event_count
        ),
    ));
    other_fields.push(render_basic_info_item(
        "Internal Call Count",
        &format!(
            "<strong>{}</strong>",
            analysis.normalized_execution_facts.internal_call_count
        ),
    ));
    other_fields.push(render_basic_info_item(
        "Input Data",
        &format!(
            "<strong>{}</strong>",
            render_copyable_code(&analysis.input_data, 14)
        ),
    ));
    let watchlist_action = if public_share {
        String::new()
    } else {
        render_watchlist_add_button(
            analysis.chain_id,
            &analysis.tx_hash,
            &tx_analysis_href(analysis.chain_id, &analysis.tx_hash),
        )
    };
    let share_top_action = if let Some(url) = share_url {
        format!(
            r#"<div class="tx-report-share-action">{}</div>"#,
            render_copyable_code(url, 16)
        )
    } else if share_action.is_empty() {
        watchlist_action
    } else {
        format!(
            r#"<div class="tx-report-share-action">{}{}</div>"#,
            share_action, watchlist_action
        )
    };
    format!(
        r#"<section class="tx-report-top tx-basic-info-panel">
  <div class="tx-report-heading">
    <span class="brand-lockup mini"><span class="brand-mark">{}</span><span>On-chain Transaction Evidence</span></span>
    <div class="tx-report-actions">
      <span class="readonly-pill">{}</span>
      {}
    </div>
  </div>
  <div class="tx-report-title-row">
    <div>
      <h1>Transaction Analysis Report</h1>
      <p>Tx Analysis Report</p>
      <span>Tx Hash</span>
      {}
    </div>
  </div>
  <div class="basic-info-card">
    <h2>Basic Information</h2>
    <div class="basic-info-grid">
      {}
    </div>
    <details class="basic-info-more">
      <summary>Other Information</summary>
      <div class="basic-info-grid">
        {}
      </div>
    </details>
  </div>
</section>"#,
        brand_mark_svg_source(),
        if public_share {
            "Public share · Read only"
        } else {
            "Analysis result"
        },
        share_top_action,
        render_copyable_code(&analysis.tx_hash, 16),
        basic_fields.join(""),
        other_fields.join(""),
    )
}

