fn classified_page_href(cluster_id: Uuid, query: &ClusterTxTableState, page: u32) -> String {
    let mut params = vec![
        "cluster_tab=activity".to_owned(),
        format!("tx_page={page}"),
        format!("tx_page_size={}", query.page_size),
        format!("tx_sort_by={}", urlencoding::encode(&query.sort_by)),
        format!("tx_sort_dir={}", urlencoding::encode(&query.sort_dir)),
    ];
    if let Some(behavior_tag) = query.behavior_tag.as_deref() {
        params.push(format!("tx_behavior={}", urlencoding::encode(behavior_tag)));
    }
    if let Some(protocol) = query.protocol.as_deref() {
        params.push(format!("tx_protocol={}", urlencoding::encode(protocol)));
    }
    format!("/app/clusters/{cluster_id}?{}", params.join("&"))
}

fn cluster_analysis_tab_href(
    cluster_id: Uuid,
    start: Option<&str>,
    end: Option<&str>,
    tab: ClusterAnalysisTab,
) -> String {
    let mut params = vec![format!("cluster_tab={}", tab.as_str())];
    if let Some(start) = start.filter(|value| !value.is_empty()) {
        params.push(format!("start={}", urlencoding::encode(start)));
    }
    if let Some(end) = end.filter(|value| !value.is_empty()) {
        params.push(format!("end={}", urlencoding::encode(end)));
    }
    format!("/app/clusters/{cluster_id}?{}", params.join("&"))
}

fn render_asset_ref(
    asset_type: &str,
    token_address: Option<&str>,
    token_symbol: Option<&str>,
    token_name: Option<&str>,
) -> String {
    if asset_type == "native" {
        return "<code>native ETH</code>".to_owned();
    }
    if token_symbol.is_some() || token_name.is_some() {
        let label = token_symbol
            .filter(|value| !value.trim().is_empty())
            .or(token_name)
            .unwrap_or("ERC20");
        let address = token_address
            .map(|value| render_copyable_code(value, 6))
            .unwrap_or_default();
        return format!(
            "<span>{}</span><small>{}</small>",
            escape_html(label),
            address
        );
    }
    token_address
        .map(|value| render_copyable_code(value, 6))
        .unwrap_or_else(|| format!("<code>{}</code>", escape_html(asset_type)))
}

fn format_asset_amount(asset_type: &str, raw: &str) -> String {
    if asset_type == "native" {
        return format_signed_wei_compact(raw);
    }
    raw.to_owned()
}

fn format_asset_display_amount(
    asset_type: &str,
    raw: &str,
    decimal: Option<&str>,
    token_symbol: Option<&str>,
) -> String {
    if let Some(decimal) = decimal {
        let symbol = if asset_type == "native" {
            "ETH"
        } else {
            token_symbol
                .filter(|value| !value.trim().is_empty())
                .unwrap_or("tokens")
        };
        return format!("{decimal} {symbol}");
    }
    format_asset_amount(asset_type, raw)
}

fn format_usd_cell(value: Option<&str>) -> String {
    value
        .map(|value| format!("${value}"))
        .unwrap_or_else(|| "n/a".to_owned())
}

fn format_signed_wei_compact(raw: &str) -> String {
    let trimmed = raw.trim();
    let negative = trimmed.starts_with('-');
    let unsigned = trimmed.trim_start_matches('-');
    let mut formatted = format_wei_compact(unsigned);
    if negative && formatted != "0 ETH" {
        formatted.insert(0, '-');
    }
    formatted
}

fn format_wei_compact(raw: &str) -> String {
    let Ok(value) = raw.trim().parse::<f64>() else {
        return raw.to_owned();
    };
    let eth = value / 1_000_000_000_000_000_000_f64;
    if eth >= 1000.0 {
        format!("{eth:.2} ETH")
    } else if eth >= 1.0 {
        format!("{eth:.4} ETH")
    } else if eth > 0.0 {
        format!("{eth:.6} ETH")
    } else {
        "0 ETH".to_owned()
    }
}

fn render_indexer_progress_panel(progress: Option<&IndexerProgressPayload>) -> String {
    let body = progress
        .map(|progress| {
            let worker_summary = if progress.workers.is_empty() {
                "No worker cursor has been committed yet.".to_owned()
            } else {
                progress
                    .workers
                    .iter()
                    .map(|worker| {
                        let detail = if worker.last_error.is_empty() {
                            worker
                                .last_success_at
                                .as_deref()
                                .map(|value| format!("last success {}", escape_html(value)))
                                .unwrap_or_else(|| "waiting for first commit".to_owned())
                        } else {
                            format!("error: {}", escape_html(&worker.last_error))
                        };
                        format!(
                            "{} / {} · block #{} · lag {} · retries {} · {}",
                            escape_html(&worker.worker_id),
                            escape_html(&worker.worker_kind),
                            worker.last_indexed_block,
                            worker.lag_blocks.unwrap_or(0),
                            worker.retry_count,
                            detail
                        )
                    })
                    .collect::<Vec<_>>()
                    .join("<br>")
            };
            format!(
                r#"<div class="stats-grid">
  <div class="stat"><span>Chain ID</span><strong>{}</strong></div>
  <div class="stat"><span>Worker ID</span><strong>{}</strong></div>
  <div class="stat"><span>RPC head</span><strong>{}</strong></div>
  <div class="stat"><span>Live cursor</span><strong>{}</strong><small>lag {} blocks</small></div>
  <div class="stat"><span>Query target block</span><strong>{}</strong></div>
  <div class="stat"><span>Max stored block</span><strong>{}</strong></div>
  <div class="stat"><span>Canonical blocks</span><strong>{}</strong><small>{} orphaned · {} reorgs</small></div>
  <div class="stat"><span>Raw transactions</span><strong>{}</strong></div>
  <div class="stat"><span>Raw logs</span><strong>{}</strong></div>
  <div class="stat"><span>Selected traces</span><strong>{}</strong></div>
  <div class="stat"><span>Lazy queue</span><strong>{}</strong><small>{} pending</small></div>
  <div class="stat"><span>Pending from/to backfill rows</span><strong>{}</strong></div>
</div>
<div class="panel-copy"><strong>Persisted workers</strong><p>{}</p></div>
<div class="panel-copy">Canonical blocks, transactions and receipt logs are read from the local chain node. Lazy address lookup runs on a separately throttled worker.</div>
<div class="button-row">
  <a class="cta secondary" href="/app/indexer/address-lookup">Open address lookup</a>
  <a class="cta ghost" href="/app/clusters">Open clusters</a>
</div>"#,
                progress.chain_id,
                escape_html(&progress.worker_id),
                progress.rpc_head_block.unwrap_or(0),
                progress.last_indexed_block,
                progress.live_lag_blocks.unwrap_or(0),
                progress
                    .query_target_block
                    .unwrap_or(progress.last_indexed_block),
                progress.max_stored_indexed_block.unwrap_or(0),
                progress.canonical_block_count,
                progress.orphaned_block_count,
                progress.reorg_count,
                progress.raw_transaction_count,
                progress.raw_log_count,
                progress.raw_trace_count,
                if progress.lazy_enabled { "enabled" } else { "disabled" },
                progress.pending_indexing_requests,
                progress.endpoint_backfill_pending_rows.unwrap_or(0),
                worker_summary,
            )
        })
        .unwrap_or_else(|| {
            "<div class=\"empty-state\">Indexer progress is unavailable right now. Check `LEDGERFLOW_INDEXER_API_BASE_URL` and the bearer token configuration.</div>".to_owned()
        });

    format!(
        r#"<section class="panel">
  <div class="panel-head"><h2>Indexer progress</h2><span class="badge">discovery layer</span></div>
  <div class="panel-body">{}</div>
</section>"#,
        body
    )
}

